    return as_date(starts[:10])


def all_rows(db, start, end, channel):
    """Every row the portal serves for [start, end], one per UID, in UID order.

    Pilot occurrences belong to the range by their 原定日 (the day encoded in
    the UID), legacy rows by the UTC day they are stored under.  An existing
    events row wins over the expanded occurrence of the same UID, so invites
    and bookings keep pointing at the row they always did.  Nothing is cut:
    a range holding more than MAX_OCCURRENCES of one series still yields every
    occurrence (V1 silently stopped at 1000).
    """
    codes = series_codes(db)
    found = {}
    for uid, starts in db.execute("select uid, starts from events order by uid"):
        day = original_day(uid, starts, codes)
        if day is not None and start <= day <= end:
            found[uid] = dict(uid=uid, utc=starts, status="CONFIRMED")
    for row in series_rows(db, start, end, channel):
        found.setdefault(row["uid"], row)       # the stored row wins
    return [found[uid] for uid in sorted(found)]


