def pages(db, query):
    """One page of the old /api/events rows, in UID order.

    `offset`/`limit` address a fixed, fully ordered list, so the same request
    always returns the same page and walking `next` visits every UID exactly
    once -- including legacy rows and series long enough to need several pages.
    """
    channel = query.get("channel", "A")
    offset = number_param(query, "offset", 0, 0)
    limit = number_param(query, "limit", DEFAULT_PAGE_LIMIT, 1)
    raw_from, raw_to = query.get("from"), query.get("to")
    if raw_from is None and raw_to is None:     # same universe as an unbounded /api/events
        rows = events(db, "1900", "2100", channel)
    else:
        start, end = as_date(raw_from), as_date(raw_to)
        if start is None or end is None:
            raise BadRequest("from and to must be ISO dates, e.g. 2026-03-06")
        if start > end:
            raise BadRequest(f"from {start} is after to {end}")
        rows = all_rows(db, start, end, channel)
    items = rows[offset:offset + limit]
    following = offset + len(items)
    return dict(items=items, next=following if following < len(rows) else None)


