def store_meta(db, table, key_columns, wanted, value_columns, version, imported):
    """Insert or update one metadata row; -> added / changed / unchanged."""
    key = tuple(wanted[column] for column in key_columns)
    where = " and ".join(f"{column}=?" for column in key_columns)
    current = db.execute("select " + ",".join(value_columns) + f" from {table} where {where}",
                         key).fetchone()
    values = tuple(wanted[column] for column in value_columns)
    if current is not None and tuple(current) == values:
        return "unchanged"
    if current is None:
        db.execute(f"insert into {table}(" + ",".join(key_columns + value_columns + ("version", "imported"))
                   + ") values(" + ",".join("?" * (len(key_columns) + len(value_columns) + 2)) + ")",
                   key + values + (version, imported))
        return "added"
    db.execute(f"update {table} set " + ",".join(f"{column}=?" for column in value_columns + ("version", "imported"))
               + f" where {where}", values + (version, imported) + key)
    return "changed"


def store_row(db, row, version, imported):
    """Upsert one business row and keep the per-version history; -> action."""
    key = (row["account"], row["code"], row["day"])
    content = tuple(row[field] for field in ROW_FIELDS)
    current = db.execute("select " + ",".join(ROW_FIELDS) + ",version from service_row"
                         " where account=? and code=? and day=?", key).fetchone()
    if current is not None and tuple(current[:-1]) == content:
        db.execute("insert or ignore into service_history(" + ",".join(HISTORY_COLUMNS) + ") values("
                   + ",".join("?" * len(HISTORY_COLUMNS)) + ")",
                   key + content + (current[-1], imported))
        return "unchanged"
    if current is None:
        db.execute("insert into service_row(account,code,day," + ",".join(ROW_FIELDS) + ",version,imported)"
                   " values(?,?,?," + ",".join("?" * (len(ROW_FIELDS) + 2)) + ")",
                   key + content + (version, imported))
        action = "added"
    else:
        db.execute("update service_row set " + ",".join(f"{field}=?" for field in ROW_FIELDS)
                   + ",version=?,imported=? where account=? and code=? and day=?",
                   content + (version, imported) + key)
        action = "changed"
    db.execute("insert or replace into service_history(" + ",".join(HISTORY_COLUMNS) + ") values("
               + ",".join("?" * len(HISTORY_COLUMNS)) + ")",
               key + content + (version, imported))
    return action


def mirror(db, rows, imported):
    """Keep the portal's own events/bookings in step; never drop an old identity."""
    seen = {}
    for row in sorted(rows, key=lambda item: item["day"]):
        starts = datetime.fromisoformat(row["utc"]).astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
        current = db.execute("select starts from events where uid=?", (row["uid"],)).fetchone()
        if current is None:
            db.execute("insert into events(uid, starts) values(?,?)", (row["uid"], starts))
        elif current[0] != starts:
            db.execute("update events set starts=? where uid=?", (starts, row["uid"]))
        seen.setdefault(row["booking"], row["uid"])
    for booking, uid in seen.items():               # a booking keeps its first occurrence UID
