def load_json(path):
    with open(path, encoding="utf-8") as handle:
        return json.load(handle)


def read_text(path):
    with open(path, encoding="utf-8") as handle:
        return handle.read().strip()


def clock_value(text, where):
    parts = str(text).split(":")
    if len(parts) != 2 or not all(part.isdigit() for part in parts):
        raise ValueError(f"{where} has no HH:MM clock: {text!r}")
    hour, minute = int(parts[0]), int(parts[1])
    if not (0 <= hour < 24 and 0 <= minute < 60):
        raise ValueError(f"{where} has an impossible clock: {text!r}")
    return time(hour, minute)


def signed(document, where):
    status = str(document.get("status", "")).lower()
    if status not in SIGNED:
        raise ValueError(f"{where} is {status or 'unsigned'}, not signed")
    return document


def annex_clocks(directory, code, spec, accounts):
    """The clocks of the signed annex the schedule points at; nothing else counts."""
    ref, approval = spec.get("ref"), spec.get("approval")
    if not ref or not approval:
        raise ValueError(f"class {code} is {BASIS_ANNEX} but names no ref/approval")
    path = os.path.join(directory, ref)
    if not os.path.isfile(path):
        raise ValueError(f"class {code} points at {ref}, which is not in {directory}")
    document = signed(load_json(path), f"annex {ref}")
    if document.get("id") != approval:
        raise ValueError(f"class {code} needs annex {approval}, but {ref} is {document.get('id')!r}")
    clocks = document.get("utc_by_account") or {}
    missing = [account for account in accounts if account not in clocks]
    if missing:
        raise ValueError(f"annex {approval} gives no UTC clock for {missing}")
    return {account: clock_value(clocks[account], f"annex {approval} / {account}")
            for account in accounts}


def migration_prefixes(directory, accounts, files):
    """Optional migration.json: after it is signed a booking's new UID prefix."""
    path = os.path.join(directory, "migration.json")
    if not os.path.isfile(path):
        return {}
    files.append("migration.json")
    document = signed(load_json(path), "migration.json")
    table = document.get("prefix_by_account") or document.get("new_prefix_by_account")
    if not isinstance(table, dict) or not table:
        raise ValueError("migration.json names no prefix_by_account")
    unknown = sorted(set(table) - set(accounts))
    if unknown:
        raise ValueError(f"migration.json names unknown accounts {unknown}")
    return {account: str(prefix).strip() for account, prefix in table.items()}


def order_days(directory, classes, accounts_by_code, files):
    """Optional orders/*.json: extra signed days for a class -> [(code, day, clocks)]."""
    folder = os.path.join(directory, "orders")
    if not os.path.isdir(folder):
        return []
    extra = []
    for name in sorted(os.listdir(folder)):
        if not name.endswith(".json"):
            continue
        rel = f"orders/{name}"
        files.append(rel)
        document = signed(load_json(os.path.join(folder, name)), rel)
        code = document.get("code")
        if code not in classes:
            raise ValueError(f"{rel} names class {code!r}, which the schedule does not have")
        raw = document.get("days") or ([document["day"]] if document.get("day") else [])
        if not raw:
            raise ValueError(f"{rel} names no day")
        need = [entry["account"] for entry in accounts_by_code.get(code, [])]
        for written in raw:
            try:
                day = date.fromisoformat(written)
            except (TypeError, ValueError):
                raise ValueError(f"{rel} names a day that is not a date: {written!r}")
            if classes[code]["basis"] == BASIS_ANNEX:
                clocks = document.get("utc_by_account") or {}
                missing = [account for account in need if account not in clocks]
                if missing:
                    raise ValueError(f"{rel} gives no UTC clock for {missing}")
                extra.append((code, day, {account: clock_value(clocks[account], f"{rel} / {account}")
                                          for account in need}))
            else:
                clock = document.get("clock") or classes[code]["clock_time"]
                extra.append((code, day, {account: clock_value(clock, f"{rel} / {account}")
                                          for account in need}))
    return extra


def business_day(directory):
    path = os.path.join(directory, "clock.txt")
    return read_text(path) if os.path.isfile(path) else ""


def declared_version(directory):
    path = os.path.join(directory, "version.txt")
    if not os.path.isfile(path):
        return None
    raw = read_text(path)
    if not raw.isdigit():
        raise ValueError(f"version.txt is not a logical version number: {raw!r}")
    return int(raw)


def make_row(registration, cls, day, prefix, clocks=None):
    if cls["basis"] == BASIS_ANNEX:
        moment = datetime.combine(day, (clocks or cls["clocks"])[registration["account"]],
                                  tzinfo=timezone.utc)
    else:
        moment = datetime.combine(day, cls["clock_time"],
                                  tzinfo=cls["zoneinfo"]).astimezone(timezone.utc)
    return dict(account=registration["account"], code=registration["code"], day=day.isoformat(),
                booking=registration["booking"], uid=f'{prefix}-{day:%Y%m%d}',
                utc=moment.isoformat(), rank=registration["rank"])


def heritage_rows(db, plan):
    """Business rows that were already in the portal before any service intake.

    The roster's old_prefix is what the earlier invitations were filed under, so
    a stored event whose UID is `<old_prefix>-YYYYMMDD` is that registration's
    row.  They become the baseline history (never rewritten by a later version).
    """
    by_prefix = {entry["old_prefix"]: entry for entry in plan["registrations"]}
    rows = []
    for uid, starts in db.execute("select uid, starts from events order by uid"):
        prefix, _, tail = uid.rpartition("-")
        registration = by_prefix.get(prefix)
        if registration is None or len(tail) != 8 or not tail.isdigit():
            continue
        try:
            day = date(int(tail[:4]), int(tail[4:6]), int(tail[6:]))
        except ValueError:
            continue
        moment = datetime.fromisoformat(starts)
        if moment.tzinfo is None:
            moment = moment.replace(tzinfo=timezone.utc)
        rows.append(dict(account=registration["account"], code=registration["code"],
                         day=day.isoformat(), booking=registration["booking"], uid=uid,
                         utc=moment.astimezone(timezone.utc).isoformat(),
                         rank=registration["rank"]))
    return rows


